# 一种求 LCA 的方法：$\text{RMQ}$

思路：一遍 DFS，求出节点的欧拉序。

然后每一次找出序列上两个点之间 `dfn` 最小的节点。

## Code:

```cpp
#include <iostream>
#include <vector>
using namespace std;
const int N = 5e5 + 10;
int dfn[N], el[N << 1], dep[N], tot = 0;
int lg2[N << 1], fa[N << 1][25];
vector<int> e[N];
inline void dfs(int u, int fa) {
    el[dfn[u] = ++tot] = u;
    dep[u]             = dep[fa] + 1;
    for (auto v : e[u]) {
        if (v == fa) continue;
        // cout << u << " -> " << v << endl;
        dfs(v, u);
        el[++tot] = u;
    }
}
inline bool cmp(int x, int y) { return dep[x] < dep[y]; }
inline void init(int cnt) {
    for (int i = 2; i <= cnt; i++) lg2[i] = lg2[i >> 1] + 1;
    for (int i = 1; i <= cnt; i++) fa[i][0] = el[i];
    for (int j = 1; j <= lg2[cnt]; j++) {
        for (int i = 1; i + (1 << j) <= cnt; i++) {
            fa[i][j] = min(fa[i][j - 1], fa[i + (1 << (j - 1))][j - 1], cmp);
            // cout << fa[i][j] << endl;
        }
    }
}
inline int ask(int l, int r) {
    int H = lg2[r - l];
    return min(fa[l][H], fa[r - (1 << H)][H], cmp);
}
int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int n, m, s;
    cin >> n >> m >> s;
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        e[u].push_back(v);
        e[v].push_back(u);
    }
    dfs(s, 0);
    dep[0] = 1e9;
    init(tot);
    while (m--) {
        int u, v;
        cin >> u >> v;
        if (u == v) {
            cout << u << endl;
            continue;
        }
        if (dfn[u] > dfn[v]) swap(u, v);
        cout << ask(dfn[u], dfn[v]) << endl;
    }
}
