vector<int> e[N];
inline void dfs(int u, int fa) {
    el[dfn[u] = ++tot] = u;
    dep[u]             = dep[fa] + 1;
    for (auto v : e[u]) {
        if (v == fa) continue;
        // cout << u << " -> " << v << endl;
        dfs(v, u);
        el[++tot] = u;
    }
}
inline bool cmp(int x, int y) { return dep[x] < dep[y]; }
inline void init(int cnt) {
    for (int i = 2; i <= cnt; i++) lg2[i] = lg2[i >> 1] + 1;
    for (int i = 1; i <= cnt; i++) fa[i][0] = el[i];
    for (int j = 1; j <= lg2[cnt]; j++) {
        for (int i = 1; i + (1 << j) <= cnt; i++) {
            fa[i][j] = min(fa[i][j - 1], fa[i + (1 << (j - 1))][j - 1], cmp);
            // cout << fa[i][j] << endl;
        }
    }
}
inline int ask(int l, int r) {
    int H = lg2[r - l];
    return min(fa[l][H], fa[r - (1 << H)][H], cmp);
}
int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int n, m, s;
    cin >> n >> m >> s;
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        e[u].push_back(v);
        e[v].push_back(u);
    }
    dfs(s, 0);
    dep[0] = 1e9;
    init(tot);
    while (m--) {
        int u, v;
        cin >> u >> v;
        if (u == v) {
            cout << u << endl;
            continue;
        }
        if (dfn[u] > dfn[v]) swap(u, v);
        cout << ask(dfn[u], dfn[v]) << endl;
    }
}
```

# 树上倍增：在 $O(\log n)$ 时间内求解一系列链上问题

一般而言，序列上的 RMQ 是相对容易的，因为你可以通过 ST 表之类的东西进行维护。

链上问题就困难一些了，因为你没法弄到一种非常优秀的方法，给每个链都搞到一个数据结构。

除非你喜欢当 M 或者数据结构学傻了，你应该不会喜欢树剖吧……

因此，树上倍增就成为了一种简洁的求解链上问题的方法。

大部分的倍增都可以理解为用长度为 $2^{i-1}$ 的两个序列拼出一个 $2^i$ 的序列。

有些时候，这个东西可以神秘：The Merchant.

```cpp
#include <cmath>
#include <iostream>
#include <stack>
#include <vector>

#pragma GCC optimize("Ofast")
#define endl      '\n'
#define min(x, y) (((x) < (y)) ? (x) : (y))
#define max(x, y) (((x) > (y)) ? (x) : (y))
// #define cin std::cin
// #define cout std::cout
// #define vector std::vector
// #define swap std::swap
// #define ios std::ios
using namespace std;
const int N = 5e4 + 10;
int fa[N][20], up[N][20], dw[N][20], mn[N][20], mx[N][20], w[N], dep[N],
    __lg[N];
namespace akioi {
inline int __lg(int x) { return ::__lg[x]; }
int n, fmin, fmax;
inline void init() {
    for (int i = 2; i <= n; i++) ::__lg[i] = ::__lg[i >> 1] + 1;
    int H = __lg(n);
    // w[0]  = 1e9;
    for (int i = 1; i <= n; i++) mn[i][0] = min(w[i], w[fa[i][0]]);
    // w[0] = 0;
    for (int i = 1; i <= n; i++) mx[i][0] = max(w[i], w[fa[i][0]]);
    for (int j = 1; j <= H; j++) {
        for (int i = 1; i <= n; i++) {
            fa[i][j] = fa[fa[i][j - 1]][j - 1];
            int f    = fa[i][j - 1];
            mn[i][j] = min(mn[i][j - 1], mn[f][j - 1]);
            mx[i][j] = max(mx[i][j - 1], mx[f][j - 1]);
            up[i][j] = max(mx[f][j - 1] - mn[i][j - 1],
                           max(up[i][j - 1], up[f][j - 1]));
            dw[i][j] = max(mx[i][j - 1] - mn[f][j - 1],
                           max(dw[i][j - 1], dw[f][j - 1]));
            // cout << f << " " << mn[i][j] << " " << mx[i][j] << endl;
        }
        // cout << endl;
    }
}
inline int qup(int u, int f) {
    int H   = __lg(n);
    int ans = 0, nmin = w[u];
    for (int i = H; i >= 0; i--) {
        if (dep[fa[u][i]] >= dep[f]) {
            ans  = max(ans, max(up[u][i], mx[u][i] - nmin));
            nmin = min(nmin, mn[u][i]);
            u    = fa[u][i];
        }
    }
    fmin = nmin;
    return ans;
}
inline int qdw(int u, int f) {
    int H   = __lg(n);
    int ans = 0, nmax = w[u];
    for (int i = H; i >= 0; i--) {
        if (dep[fa[u][i]] >= dep[f]) {
            ans  = max(ans, max(dw[u][i], nmax - mn[u][i]));
            nmax = max(nmax, mx[u][i]);
            u    = fa[u][i];
        }
    }
    fmax = nmax;
    return ans;
}
vector<int> e[N];
struct node {
    int u, fa;
};
inline void dfs(int u, int fa) {
    stack<node> st;
    node nw;
    nw.u  = u;
    nw.fa = fa;
    st.push(nw);
    while (!st.empty()) {
        nw = st.top();
        st.pop();
        int fa = nw.fa, u = nw.u;
        ::fa[u][0] = fa;
        dep[u]     = dep[fa] + 1;
        for (int i = 0; i < e[u].size(); i++) {
            int v = e[u][i];
            if (v == fa) continue;
            nw.u  = v;
            nw.fa = u;
        // cerr << u << " " << v << endl;
            st.push(nw);
        }
    }
}
inline int LCA(int u, int v) {
    int H = __lg(n);
    if (dep[v] > dep[u]) swap(u, v);
    for (int i = H; i >= 0; i--) {
        if (dep[fa[u][i]] >= dep[v]) u = fa[u][i];
    }
    if (u == v) return u;
    for (int i = H; i >= 0; i--) {
        if (fa[u][i] != fa[v][i]) u = fa[u][i], v = fa[v][i];
    }
    return fa[u][0];
}
} // namespace akioi
int main() {
    // freopen("test.in", "r", stdin);
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    cin >> akioi::n;
    // cerr << __LINE__ << endl;
    for (int i = 1; i <= akioi::n; i++) cin >> w[i];
    for (int i = 1; i < akioi::n; i++) {
        int u, v;
        cin >> u >> v;
        akioi::e[u].push_back(v);
        akioi::e[v].push_back(u);
    }
    // cerr << __LINE__ << endl;
    akioi::dfs(1, 0);
    // cerr << __LINE__ << endl;
    akioi::init();
    // cerr << __LINE__ << endl;
    // cout << akioi::__lg(1024) << endl;
    int q;
    cin >> q;
    while (q--) {
        int u, v;
        cin >> u >> v;
        int l  = akioi::LCA(u, v);
        int up = akioi::qup(u, l);
        int dw = akioi::qdw(v, l);
        // cout << up << " " << dw << " " << fmax << " " << fmin << endl;
        cout << max(akioi::fmax - akioi::fmin, max(up, dw)) << endl;
    }
}
