# 树上差分

就是记录从这个节点到根的路径上，每一个节点的权值都加上某个数（也不一定是加，乘除什么的都行）。

听上去老简单了，如果要给一条链增加一些东西，则：

1. 如果是要给路径的点，这个比较容易理解，将 $u$ 和 $v$ 加上 $x$，这样 $\text{LCA}(u, v)$ 以及它的所有父亲都被算了两次，我们要给 $\text{LCA}$ 减去 $x$，给 $\text{LCA}$ 的父亲再减去 $x$。

2. 如果是要给路径的边，我们一般用这条边的儿子端来代表这条边。此时我们给 $u$ 和 $v$ 加上 $x$，然后直接给 $\text{LCA}(u,v)$ 减去 $x$ 即可。

模板略，这些例题比较有意思：

## 疫情控制

这玩意就是二分时间，然后让能跳的可着劲往上跳（因为显然跳到根节点的儿子是不劣于待在原地的），然后如果一个军队到了根节点就没法守家了（也就是说，他到了根节点就没有时间回来了），那么他就不如待在自己家（因为他就算能支援，也只能支援那些距离根节点比他近的，而如果他压根不离开，就等效于他出去又回来，走了更多的路。）

代码非常好写.jpg

```cpp
#include <algorithm>
#include <cstdio>
#include <cstring>
#include <iostream>
#include <vector>
using namespace std;
const int N = 1e5 + 10;
struct edge {
    int v, w;
};
vector<edge> e[N];
using ll = long long;
int fa[N][20], n, m, loc[N], bel[N], jp[N];
ll dis[N][20], dst[N];
bool vis[N];
inline void init() {
    int H = __lg(n);
    for (int j = 1; j <= H; j++) {
        for (int i = 1; i <= n; i++) {
            fa[i][j]  = fa[fa[i][j - 1]][j - 1];
            dis[i][j] = dis[i][j - 1] + dis[fa[i][j - 1]][j - 1];
        }
    }
}
inline void dfs1(int u, int fa, int c) {
    // cout << u << " " << fa << endl;
    dis[u][0]  = c;
    ::fa[u][0] = fa;
    for (auto p : e[u]) {
        int v = p.v, w = p.w;
        if (v == fa) continue;
        dfs1(v, u, w);
    }
}
inline bool dfs2(int u, int fa) {
    if (vis[u] && (fa - 1)) return 1;
    bool ans = (e[u].size() - 1);
    for (auto p : e[u]) {
        int v = p.v;
        if (v == fa) continue;
        ans &= dfs2(v, u);
        if (!ans) return false;
    }
    return ans;
}
// #define debug
inline bool check(ll x) {
#ifdef debug
    cout << "# " << x << endl;
#endif
    memset(vis, 0, sizeof(vis));
    vector<int> reach, req;
    vector<bool> prt(N), rp(N);
    int H = __lg(n);
    for (int i = 1; i <= m; i++) {
        if (dst[loc[i]] <= x) {
            int u = jp[loc[i]] = bel[loc[i]];
            if (dst[loc[i]] + 2 * dis[bel[loc[i]]][0] > x) rp[u] = prt[u] = 1;
        } else {
            int u = loc[i], nx = x;
            for (int i = H; i >= 0; i--) {
                if (dis[u][i] <= nx) nx -= dis[u][i], u = fa[u][i];
            }
            jp[loc[i]] = u;
        }
        vis[jp[loc[i]]] = 1;

        // cout << jp[loc[i]] << " ";
    }
    // cout << endl;
    for (auto p : e[1]) {
        if (prt[p.v]) continue;
        bool pt = dfs2(p.v, fa[p.v][0]);
        if (pt) prt[p.v] = 1;
        else req.push_back(p.v);
    }
    for (int i = 1; i <= m; i++)
        if ((!rp[bel[loc[i]]] && prt[bel[loc[i]]]) ||
            dst[loc[i]] + 2 * dis[bel[loc[i]]][0] <= x) {
            reach.push_back(loc[i]);
        } else prt[bel[loc[i]]] = 1, rp[bel[loc[i]]] = 0;
    sort(reach.begin(), reach.end(), [](int a, int b) {
        return (dst[a] + dis[bel[a]][0] > dst[b] + dis[bel[b]][0]);
    });
    sort(req.begin(), req.end(),
         [](int a, int b) { return dis[a][0] < dis[b][0]; });
    auto p = reach.begin();
#ifdef debug
    cout << "Reach:";
    for (auto p : reach) cout << p << " ";
    cout << endl;
    cout << "Req:";
    for (auto p : req) cout << p << " ";
    cout << endl;
#endif
    for (auto u : req) {
        bool ok = 0;
        for (; p != reach.end(); p++) {
            ll len = dis[bel[*p]][0] + dis[u][0];
            if (x - dst[*p] >= len) {
                ok = 1;
#ifdef debug
                cout << "Match:" << *p << " " << u << " " << len << endl;
#endif
                ++p;
                break;
            }
        }
        if (!ok) return 0;
    }
    return 1;
}
int main() {
    // freopen("P1084_7.in", "r", stdin);
    cin >> n;
    for (int i = 1; i < n; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        e[u].push_back((edge){v, w});
        e[v].push_back((edge){u, w});
    }
    sort(e[1].begin(), e[1].end(), [](edge x, edge y) { return x.w < y.w; });
    cin >> m;
    for (int i = 1; i <= m; i++) cin >> loc[i], vis[loc[i]] = 1;
    dfs1(1, 0, 0);
    init();
    int H = __lg(n);
    for (int i = 1; i <= n; i++) {
        int u = i;
        for (int j = H; j >= 0; j--) {
            if (fa[u][j] > 1) dst[i] += dis[u][j], u = fa[u][j];
        }
        // cout << fa[9][0] << " " << fa[9][1] << endl;
        // cout << i << " " << dst[i] << endl;
        bel[i] = u;
    }
    sort(loc + 1, loc + 1 + m, [](int x, int y) { return dst[x] > dst[y]; });
    ll l = 0, r = 1e15;
    while (l < r) {
        ll mid = (l + r) >> 1;
        if (check(mid)) r = mid;
        else l = mid + 1;
    }
    if (l != 1e15) cout << l << endl;
    else cout << -1 << endl;
}
```

## 天天爱跑步

这个就是一个经典的套路：对于某种会以某种恒定的方式动的东西，我们记录一些不会变的东西，就可以确定他的状态。

比如说，我有一个箱子，在 $i$ 秒在 $x$ 位置出现，以 $1m/s$ 的速度在向右运动，那么我们就可以将它看作一个第 $0$ 秒从 $x-i$ 位置出现的箱子，但是这个箱子**只存在于 $x$ 向右的位置**。

有了这一点，这个问题就比较简单了。

这个代码至少比上一个简单。

```cpp
#include <iostream>
#include <vector>
using namespace std;
const int N = 2e6 + 10, PY = 6e5 + 10;
vector<int> e[N], add[N][2], del[N][2];
int fa[N][30], dep[N], w[N], n, m;
int cnt[N][2], ans[N];
inline void init() {
    int H = __lg(n);
    for (int j = 1; j <= H; j++) {
        for (int i = 1; i <= n; i++) { fa[i][j] = fa[fa[i][j - 1]][j - 1]; }
    }
}
inline void dfs1(int u, int fa) {
    ::fa[u][0] = fa;
    dep[u]     = dep[fa] + 1;
    for (auto v : e[u]) {
        if (v == fa) continue;
        dfs1(v, u);
    }
}
inline int LCA(int x, int y) {
    int H = __lg(n);
    if (dep[x] < dep[y]) swap(x, y);
    for (int i = H; i >= 0; i--) {
        if (dep[fa[x][i]] >= dep[y]) x = fa[x][i];
    }
    if (x == y) return x;
    for (int i = H; i >= 0; i--) {
        if (fa[x][i] != fa[y][i]) {
            x = fa[x][i];
            y = fa[y][i];
        }
    }
    return fa[x][0];
}
inline void dfs2(int u, int fa) {
    int beg1 = 0, beg2 = 0;
    beg1 = cnt[dep[u] + w[u]][0];
    beg2 = cnt[w[u] - dep[u] + PY][1];
    for (auto v : del[u][0]) cnt[v][0]--;
    for (auto v : del[u][1]) cnt[v][1]--;
    for (auto v : add[u][0]) cnt[v][0]++;
    for (auto v : add[u][1]) cnt[v][1]++;
    for (auto v : e[u]) {
        if (v == fa) continue;
        dfs2(v, u);
    }
    ans[u] = cnt[dep[u] + w[u]][0] - beg1;
    ans[u] += cnt[w[u] - dep[u] + PY][1] - beg2;
    // cout << u << endl;
    // for (int i = -n; i <= n; i++) cout << cnt[i + PY][1] << " ";
    // cout << endl;
}
int main() {
    cin >> n >> m;
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        e[u].push_back(v);
        e[v].push_back(u);
    }
    for (int i = 1; i <= n; i++) cin >> w[i];
    dfs1(1, 0);
    init();
    for (int i = 1; i <= m; i++) {
        int u, v;
        cin >> u >> v;
        int l = LCA(v, u);
        add[u][0].push_back(dep[u]);
        del[fa[l][0]][0].push_back(dep[u]);
        add[v][1].push_back(dep[u] - 2 * dep[l] + PY);
        del[l][1].push_back(dep[u] - 2 * dep[l] + PY);
    }
    dfs2(1, 0);
    for (int i = 1; i <= n; i++) cout << ans[i] << " ";
    cout << endl;
}
```

