        int v=e[x][i];
        if(!dfn[v])tarjan(v),low[x]=min(low[x],low[v]);
        else low[x]=min(low[x],dfn[v]);
    }
    if(dfn[x]<=low[x]){
        // 实力不详，遇强则强
    }
